import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new THREE.Group();
  group.name = 'journal-thumbnail-card';

  // --- dimensions -----------------------------------------------------
  const cardWidth = 1.7;
  const imageHeight = 1.0;
  const captionHeight = 0.32;
  const totalHeight = imageHeight + captionHeight;

  const imageCenterY = totalHeight / 2 - imageHeight / 2;
  const captionCenterY = -totalHeight / 2 + captionHeight / 2;

  // --- machined frame (backing plate, PBR) -----------------------------
  const frameGeo = new THREE.BoxGeometry(cardWidth + 0.06, totalHeight + 0.06, 0.06);
  const frameMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.18,
    clearcoatRoughness: 0.4,
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.03);
  group.add(frame);

  // --- image plane (unlit, brightest element of the card) -------------
  const imageGeo = new THREE.PlaneGeometry(cardWidth - 0.04, imageHeight - 0.04);
  const imageMat = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.0,
  });
  const imagePlane = new THREE.Mesh(imageGeo, imageMat);
  imagePlane.position.set(0, imageCenterY, 0.005);
  group.add(imagePlane);

  // fallback tinted card while the image streams in
  const placeholderGeo = new THREE.PlaneGeometry(cardWidth - 0.04, imageHeight - 0.04);
  const placeholderMat = new MeshBasicNodeMaterial({ color: colors.surface });
  const placeholder = new THREE.Mesh(placeholderGeo, placeholderMat);
  placeholder.position.set(0, imageCenterY, 0.004);
  group.add(placeholder);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      imageMat.map = tex;
      imageMat.opacity = 1.0;
      imageMat.needsUpdate = true;
      placeholder.visible = false;
    }).catch(() => {
      placeholder.visible = true;
    });
  }

  // --- caption strip (surface tone, mono-caption register) -------------
  const captionGeo = new THREE.BoxGeometry(cardWidth - 0.04, captionHeight - 0.04, 0.02);
  const captionMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.2,
  });
  const captionStrip = new THREE.Mesh(captionGeo, captionMat);
  captionStrip.position.set(0, captionCenterY, 0.005);
  group.add(captionStrip);

  // --- accent edge line (focus / hover indicator, <=10% of frame) ------
  const accentGeo = new THREE.PlaneGeometry(cardWidth - 0.04, 0.018);
  const accentMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.0,
  });
  const accentLine = new THREE.Mesh(accentGeo, accentMat);
  accentLine.position.set(0, captionCenterY + captionHeight / 2 - 0.006, 0.02);
  group.add(accentLine);

  // ---------------------------------------------------------------------
  // interaction state
  // ---------------------------------------------------------------------
  const baseScale = { x: 1, y: 1, z: 1 };
  const timelines = [];

  function makeTl() {
    const tl = gsap.timeline();
    timelines.push(tl);
    return tl;
  }

  function onHoverStart() {
    const tl = makeTl();
    tl.to(group.position, { y: '+=0.15', duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(group.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(accentMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverEnd() {
    const tl = makeTl();
    tl.to(group.position, { y: '-=0.15', duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(group.scale, { x: baseScale.x, y: baseScale.y, z: baseScale.z, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(accentMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onPress() {
    const tl = makeTl();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  }

  function onRelease() {
    const tl = makeTl();
    tl.to(group.scale, {
      x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power4.out',
      onComplete: () => {
        gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.55, ease: 'power4.out' });
      },
    });
  }

  function onClick() {
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'journal-thumbnail-card' });
  }

  group.userData.handlers = {
    onPointerEnter: onHoverStart,
    onPointerOver: onHoverStart,
    onHoverStart,
    onPointerLeave: onHoverEnd,
    onPointerOut: onHoverEnd,
    onHoverEnd,
    onPointerDown: onPress,
    onPress,
    onPointerUp: onRelease,
    onRelease,
    onClick,
    onSelect: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    frameGeo.dispose();
    frameMat.dispose();
    imageGeo.dispose();
    imageMat.map?.dispose();
    imageMat.dispose();
    placeholderGeo.dispose();
    placeholderMat.dispose();
    captionGeo.dispose();
    captionMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
